{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:wexp:coverage:pg-ledger:0.2.0:snapshot",
  "title": "PG Ledger 0.2.0 raw snapshot (structural validity only)"\
    ,
  "type": "object",
  "additionalProperties": false,
  "required": ["profile", "version", "server_version", "snapshot_coo\
    rdinate", "epoch", "actions", "finalization_attempts", "receiver\
    _attempts"],
  "properties": {
    "profile": {"const": "wexp-coverage-pg-ledger"},
    "version": {"const": "0.2.0"},
    "server_version": {"type": "string", "pattern": "^18(?:[. ]|$)"\
    , "maxLength": 256},
    "snapshot_coordinate": {"type": "string", "pattern": "^[0-9]+:[0\
    -9]+:([0-9]+(,[0-9]+)*)?$", "maxLength": 262144},
    "epoch": {
      "type": "object", "additionalProperties": false,
      "required": ["epoch_id", "database_incarnation", "recipient_id\
    ", "issuer_id", "issuer_key_id_hex", "issuer_public_key_hex", "p\
    olicy_digest_hex", "action_seal_xid", "creation_seal_xid", "rece\
    iver_seal_xid"],
      "properties": {
        "epoch_id": {"$ref": "#/$defs/uuid"},
        "database_incarnation": {"$ref": "#/$defs/uuid"},
        "recipient_id": {"type": "string", "minLength": 1, "maxLengt\
    h": 256},
        "issuer_id": {"type": "string", "minLength": 1, "maxLength"\
    : 256},
        "issuer_key_id_hex": {"type": "string", "pattern": "^([0-9a-\
    f]{2}){1,64}$"},
        "issuer_public_key_hex": {"$ref": "#/$defs/hex32"},
        "policy_digest_hex": {"$ref": "#/$defs/hex32"},
        "action_seal_xid": {"$ref": "#/$defs/decimal"},
        "creation_seal_xid": {"$ref": "#/$defs/decimal"},
        "receiver_seal_xid": {"$ref": "#/$defs/decimal"}
      }
    },
    "actions": {
      "type": "array", "maxItems": 10000,
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["action_id", "payload_hex"],
        "properties": {
          "action_id": {"$ref": "#/$defs/uuid"},
          "payload_hex": {"type": "string", "pattern": "^([0-9a-f]{2\
    })*$", "maxLength": 2097152}
        }
      }
    },
    "finalization_attempts": {"type": "array", "maxItems": 10000, "i\
    tems": {"$ref": "#/$defs/attempt"}},
    "receiver_attempts": {"type": "array", "maxItems": 10000, "items\
    ": {"$ref": "#/$defs/attempt"}}
  },
  "$defs": {
    "uuid": {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-\
    [0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
    "decimal": {"type": "string", "pattern": "^[1-9][0-9]{0,19}$"},
    "hex32": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "attempt": {
      "type": "object", "additionalProperties": false,
      "required": ["entry_id", "receipt_key", "final_bytes_hex"],
      "properties": {
        "entry_id": {"$ref": "#/$defs/decimal"},
        "receipt_key": {"$ref": "#/$defs/uuid"},
        "final_bytes_hex": {"type": "string", "pattern": "^([0-9a-f]\
    {2})*$", "maxLength": 131072}
      }
    }
  }
}

