{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:wexp:coverage:pg-ledger:0.2.0:adapter-input",
  "title": "Detached evidence package for the PG Ledger adapter",
  "type": "object", "additionalProperties": false,
  "required": ["profile", "version", "request", "snapshot", "pinned_\
    policy", "evidence"],
  "properties": {
    "profile": {"const": "wexp-coverage-pg-ledger"},
    "version": {"const": "0.2.0"},
    "request": {
      "type": "object", "additionalProperties": false,
      "required": ["request_id", "rule_set", "requested_claims", "as\
    sumption_policy"],
      "properties": {
        "request_id": {"type": "string", "pattern": "^[A-Za-z0-9._-]\
    {1,64}$"},
        "rule_set": {"const": "coverage/0.2.0"},
        "requested_claims": {"type": "array", "minItems": 1, "maxIte\
    ms": 10, "uniqueItems": true, "items": {"enum": ["supplied-corre\
    spondence", "source-complete", "source-sound", "source-exact", "\
    creation-complete", "creation-sound", "creation-exact", "deliver\
    y-complete", "delivery-exact", "empty-actions"]}},
        "assumption_policy": {"$ref": "#/$defs/artifact"}
      }
    },
    "snapshot": {"$ref": "#/$defs/artifact"},
    "pinned_policy": {"$ref": "#/$defs/artifact"},
    "evidence": {
      "type": "array", "maxItems": 128,
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["id", "kind", "artifact"],
        "properties": {
          "id": {"type": "string", "pattern": "^[A-Za-z0-9._-]{1,64}\
    $"},
          "kind": {"enum": ["policy-approval", "collection-provenanc\
    e", "schema-grants-audit", "durability-continuity", "seal-transc\
    ript", "publication-discipline", "recipient-possession"]},
          "artifact": {"$ref": "#/$defs/artifact"}
        }
      }
    }
  },
  "$defs": {
    "artifact": {
      "type": "object", "additionalProperties": false,
      "required": ["name", "sha256", "octets"],
      "properties": {
        "name": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-\
    9._-]{0,127}$"},
        "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "octets": {"type": "integer", "minimum": 0, "maximum": 26843\
    5456}
      }
    }
  }
}

NOTE: '\' line wrapping per RFC 8792

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:wexp:coverage:pg-ledger:0.2.0:assumption-policy",
  "title": "Explicit assumption acceptance policy (approval authenti\
    cation is external)",
  "type": "object", "additionalProperties": false,
  "required": ["policy_id", "version", "authority", "database_incarn\
    ation", "epoch_id", "accepted_assumptions"],
  "properties": {
    "policy_id": {"type": "string", "minLength": 1, "maxLength": 128\
    },
    "version": {"type": "string", "minLength": 1, "maxLength": 64},
    "authority": {"type": "string", "minLength": 1, "maxLength": 256\
    },
    "database_incarnation": {"type": "string", "pattern": "^[0-9a-f]\
    {8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
    "epoch_id": {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]\
    {4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
    "accepted_assumptions": {
      "type": "array", "maxItems": 128,
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["id", "predicate", "predicate_version", "reason\
    ", "limitations"],
        "properties": {
          "id": {"type": "string", "pattern": "^[A-Za-z0-9._-]{1,64}\
    $"},
          "predicate": {"enum": ["trusted-database-host-administrati\
    on", "correct-postgresql-storage", "exclusive-principal-capabili\
    ties", "publisher-obeys-finalization-order", "recipient-service-\
    obeys-inbox-contract"]},
          "predicate_version": {"const": "pg-ledger/0.2.0"},
          "reason": {"type": "string", "minLength": 1, "maxLength": \
    2048},
          "limitations": {"type": "array", "maxItems": 128, "items"\
    : {"type": "string", "maxLength": 2048}}
        }
      }
    }
  }
}

