{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:wexp:coverage:pg-ledger:0.2.0:adapter-result",
  "title": "Profile evidence-check report, not a CoverageResult",
  "type": "object", "additionalProperties": false,
  "required": ["profile", "version", "adapter_status", "input_sha25\
    6", "checks", "diagnostics"],
  "allOf": [{"if": {"properties": {"adapter_status": {"const": "eva\
    luated"}}}, "then": {"properties": {"input_sha256": {"type": "s\
    tring", "pattern": "^[0-9a-f]{64}$"}}}}],
  "properties": {
    "profile": {"const": "wexp-coverage-pg-ledger"},
    "version": {"const": "0.2.0"},
    "adapter_status": {"enum": ["not-evaluated", "rejected", "evalu\
    ated"]},
    "input_sha256": {"oneOf": [{"type": "null"}, {"type": "string"\
    , "pattern": "^[0-9a-f]{64}$"}]},
    "checks": {
      "type": "object", "additionalProperties": false,
      "required": ["structure", "policy", "capture_authenticity", "\
    schema_grants", "durability_continuity", "barriers", "finalizat\
    ion_publication", "receiver_possession", "receipt_binding"],
      "properties": {
        "structure": {"$ref": "#/$defs/check"},
        "policy": {"$ref": "#/$defs/check"},
        "capture_authenticity": {"$ref": "#/$defs/check"},
        "schema_grants": {"$ref": "#/$defs/check"},
        "durability_continuity": {"$ref": "#/$defs/check"},
        "barriers": {"$ref": "#/$defs/check"},
        "finalization_publication": {"$ref": "#/$defs/check"},
        "receiver_possession": {"$ref": "#/$defs/check"},
        "receipt_binding": {"$ref": "#/$defs/check"}
      }
    },
    "diagnostics": {"type": "array", "maxItems": 1000, "items": {"$\
    ref": "#/$defs/diagnostic"}}
  },
  "$defs": {
    "check": {
      "type": "object", "additionalProperties": false,
      "required": ["status", "evidence_refs", "reason"],
      "properties": {
        "status": {"description": "conflicted is reserved: profile \
    0.2.0 producers MUST NOT emit it; semantic validators MUST reje\
    ct reports containing it.", "enum": ["not-evaluated", "supporte\
    d", "refuted", "unresolved", "conflicted"]},
        "evidence_refs": {"type": "array", "maxItems": 128, "unique\
    Items": true, "items": {"type": "string", "pattern": "^[A-Za-z0\
    -9._-]{1,64}$"}},
        "reason": {"type": "string", "minLength": 1, "maxLength": 2\
    048}
      }
    },
    "diagnostic": {
      "type": "object", "additionalProperties": false,
      "required": ["code", "location", "detail"],
      "properties": {
        "code": {"enum": ["NOT_IMPLEMENTED", "INPUT_INVALID", "UNSU\
    PPORTED_VERSION", "UNKNOWN_FIELD", "RESOURCE_LIMIT", "HASH_MISM\
    ATCH", "EVIDENCE_MISSING", "AUTHENTICITY_UNRESOLVED", "POLICY_M\
    ISMATCH", "BARRIER_UNESTABLISHED", "COLLECTION_INCOMPLETE", "CO\
    NFIG_DISCONTINUITY", "RECEIPT_INVALID", "IDENTITY_CONFLICT", "B\
    INDING_UNRESOLVED"]},
        "location": {"type": "string", "maxLength": 256},
        "detail": {"type": "string", "minLength": 1, "maxLength": 2\
    048}
      }
    }
  }
}

section.t:
The recipient is r, the issuer is i, and the action
      payload is the empty byte string. The exact 113-byte policy encoding
      from  is:
